from collections import Counter

class Solution:
    def similarPairs(self, words: list[str]) -> int:
        counts = Counter()
        for w in words:
            mask = 0
            for ch in w:
                mask |= 1 << (ord(ch) - 97)
            counts[mask] += 1
        return sum(c * (c - 1) // 2 for c in counts.values())

class Solution {
public:
    int similarPairs(std::vector<std::string>& words) {
        std::unordered_map<int, int> counts;
        for (const auto& w : words) {
            int mask = 0;
            for (char ch : w) mask |= (1 << (ch - 'a'));
            counts[mask]++;
        }
        int ans = 0;
        for (auto& [mask, c] : counts) {
            ans += c * (c - 1) / 2;
        }
        return ans;
    }
};

class Solution {
    public int similarPairs(String[] words) {
        java.util.Map<Integer, Integer> counts = new java.util.HashMap<>();
        for (String w : words) {
            int mask = 0;
            for (int i = 0; i < w.length(); i++) {
                mask |= (1 << (w.charAt(i) - 'a'));
            }
            counts.put(mask, counts.getOrDefault(mask, 0) + 1);
        }
        int ans = 0;
        for (int c : counts.values()) {
            ans += c * (c - 1) / 2;
        }
        return ans;
    }
}

var similarPairs = function(words) {
    const counts = new Map();
    for (const w of words) {
        let mask = 0;
        for (let i = 0; i < w.length; i++) {
            mask |= (1 << (w.charCodeAt(i) - 97));
        }
        counts.set(mask, (counts.get(mask) || 0) + 1);
    }
    let ans = 0;
    for (const c of counts.values()) {
        ans += Math.floor(c * (c - 1) / 2);
    }
    return ans;
};
